'use strict';
/* Accounting (M-ACC): chart of accounts, journals, payables, bank, statements, period close, tax, fixed assets, payroll */

const ACC_TABS = [{ k: 'accounts', l: 'Chart of accounts' }, { k: 'ledger', l: 'General ledger' }, { k: 'journals', l: 'Journals' }, { k: 'payables', l: 'Payables' }, { k: 'receivables', l: 'Receivables' }, { k: 'bank', l: 'Bank' }, { k: 'statements', l: 'Statements' }, { k: 'consol', l: 'Group consolidation' }, { k: 'consol', l: 'Group consolidation' }, { k: 'periods', l: 'Period close' }, { k: 'tax', l: 'Tax' }, { k: 'assets', l: 'Fixed assets' }, { k: 'payroll', l: 'Payroll journal' }];
const accW = () => modAccess('accounting') === 'write' && can('acc.journal');

PAGES.accounting = (parts, q) => {
  const tab = parts[0] || 'accounts'; const fy = fiscalYear();
  const pend = DB.q('journals').filter(j => j.status === 'pending').length;
  let body = ''; if (tab === 'accounts') body = accAccounts(); else if (tab === 'ledger') body = accLedger(); else if (tab === 'receivables') body = accReceivables(); else if (tab === 'journals') body = accJournals(); else if (tab === 'payables') body = accPayables(); else if (tab === 'bank') body = accBank(); else if (tab === 'statements') body = accStatements(parts[1] || 'pnl'); else if (tab === 'consol') body = accConsol(); else if (tab === 'periods') body = accPeriods(); else if (tab === 'tax') body = accTax(); else if (tab === 'assets') body = accAssets(); else if (tab === 'payroll') body = accPayroll();
  openFromQuery('j', id => openJournal(id));
  return pageHead({ title: `Accounting${pi('calc', true)}built in`, sub: `${esc(company().name)} · ${fy.label} (1 July – 30 June) · double-entry ledger · ${pend} journals awaiting approval`, acts: accW() ? `<button class="btn primary" data-act="jv.new">${icon('plus', 'sm')} Manual journal</button>` : '' }) + tabs('accounting', ACC_TABS, tab) + body;
};

/* ---------- chart of accounts ---------- */
function accAccounts() {
  const fy = fiscalYear(); const tb = trialBalance(null, today()); const rows = () => trialBalance(null, today()).map(a => ({ id: a.code, ...a }));
  return table({ id: 'coa', title: 'Chart of accounts', rows, ph: 'Search accounts', sort: { k: 'code', dir: 1 }, ps: 30, onRow: a => openLedger(a.code), filters: [{ k: 'type', l: 'Type', o: Object.entries(ACCT_TYPES), get: a => a.type }], tools: accW() ? `<button class="btn sm primary" data-act="acct.new">${icon('plus', 'sm')} Add account</button>` : '', cols: [{ k: 'code', l: 'Code' }, { k: 'name', l: 'Account' }, { k: 'type', l: 'Type', r: a => ACCT_TYPES[a.type], x: a => ACCT_TYPES[a.type] }, { k: 'dr', l: 'Debits', num: true, r: a => money(a.dr) }, { k: 'cr', l: 'Credits', num: true, r: a => money(a.cr) }, { k: 'bal', l: 'Balance', num: true, r: a => money(a.bal) }] });
}
ACT['acct.new'] = () => openForm({ title: 'Add account', fields: [{ n: 'code', l: 'Code', req: true, half: true, vf: v => acctByCode(v) ? 'This code already exists.' : '' }, { n: 'type', l: 'Type', t: 'select', req: true, half: true, o: Object.entries(ACCT_TYPES) }, { n: 'name', l: 'Account name', req: true }], onSubmit: v => { DB.add('accounts', v); render(); } });
function openLedger(code) {
  openDrawer(() => { const a = acctByCode(code); if (!a) return null; const debitNormal = ['asset', 'expense'].includes(a.type); let run = 0; const lines = []; DB.q('journals').filter(j => j.status === 'posted').sort(by(j => j.date + j.no)).forEach(j => j.lines.filter(l => l.acct === code).forEach(l => { run += debitNormal ? l.dr - l.cr : l.cr - l.dr; lines.push({ j, l, run }); }));
    return { title: esc(code + ' · ' + a.name), body: `<div class="stat" style="margin-bottom:14px"><b>${money(run)}</b><span>${ACCT_TYPES[a.type]} · ${lines.length} postings</span></div><table class="tbl"><thead><tr><th>Date</th><th>Journal</th><th class="num">Debit</th><th class="num">Credit</th><th class="num">Balance</th></tr></thead><tbody>${lines.slice(-60).reverse().map(x => `<tr class="clk" data-act="jv.open" data-id="${x.j.id}"><td>${fmtDate(x.j.date)}</td><td>${esc(x.j.no)}<div class="small muted">${esc(x.j.memo)}</div></td><td class="num">${x.l.dr ? money(x.l.dr) : ''}</td><td class="num">${x.l.cr ? money(x.l.cr) : ''}</td><td class="num">${money(x.run)}</td></tr>`).join('')}</tbody></table>${lines.length > 60 ? '<p class="small muted">Showing the latest 60 postings.</p>' : ''}`, foot: '<button class="btn" data-act="ov.close">Close</button>' };
  }, { wide: true });
}

/* ---------- journals ---------- */
function journalTable(j) { return `<table class="tbl"><thead><tr><th>Account</th><th>Dept</th><th class="num">Debit</th><th class="num">Credit</th></tr></thead><tbody>${j.lines.map(l => `<tr><td>${esc(acctLabel(l.acct))}</td><td>${esc(l.dept || '')}</td><td class="num">${l.dr ? money(l.dr) : ''}</td><td class="num">${l.cr ? money(l.cr) : ''}</td></tr>`).join('')}<tr><th colspan="2">Total</th><th class="num">${money(sum(j.lines, l => l.dr))}</th><th class="num">${money(sum(j.lines, l => l.cr))}</th></tr></tbody></table>`; }
function accJournals() {
  const rows = () => DB.q('journals').map(j => ({ ...j, byName: userName(j.by) }));
  return table({ id: 'journals', title: 'Journals', rows, ph: 'Search journals, memos or sources', sort: { k: 'date', dir: -1 }, onRow: j => openJournal(j.id), filters: [{ k: 'status', l: 'Status', o: ['posted', 'pending', 'rejected', 'reversed'], get: j => j.status }, { k: 'source', l: 'Source', o: ['manual', 'payment', 'sale', 'commission', 'expense', 'bill', 'invoice', 'payroll', 'depr', 'asset', 'tax'], get: j => j.source }], cols: [{ k: 'no', l: 'Journal' }, { k: 'date', l: 'Date', r: j => fmtDate(j.date), sv: j => j.date }, { k: 'memo', l: 'Memo' }, { k: 'source', l: 'Source', r: j => `<span class="tag">${esc(j.source)}</span>`, x: j => j.source }, { k: 'total', l: 'Amount', num: true, r: j => money(j.total) }, { k: 'status', l: 'Status', r: j => spill(j.status) }] });
}
ACT['jv.open'] = el => openJournal(el.dataset.id);
function openJournal(id) {
  openDrawer(() => { const j = DB.get('journals', id); if (!j) return null; const a = DB.q('approvals').find(x => x.type === 'journal' && x.ref === id);
    return { title: esc(j.no) + ' · ' + esc(j.memo), body: `<div class="row" style="margin-bottom:12px">${spill(j.status)}<span class="tag">${esc(j.source)}</span></div>${kv([['Date', fmtDate(j.date)], ['Raised by', esc(userName(j.by))], ['Reference', esc(j.ref || '—')], j.note ? ['Note', esc(j.note)] : null])}<div class="sec"><h4>Lines</h4>${journalTable(j)}</div>${a ? `<div class="sec"><h4>Approval</h4>${chainView(a)}</div>` : ''}`, foot: (a && canDecide(a) ? `<button class="btn danger" data-act="appr.reject" data-id="${a.id}">Reject</button><button class="btn primary" data-act="appr.approve" data-id="${a.id}">Approve</button>` : '') + (j.status === 'posted' && accW() && j.source === 'manual' ? `<button class="btn" data-act="jv.reverse" data-id="${id}">Reverse</button>` : '') || '<button class="btn" data-act="ov.close">Close</button>' };
  }, { wide: true });
}
ACT['jv.reverse'] = el => { const j = DB.get('journals', el.dataset.id); askText('Reverse journal', 'Reason', n => { try { const r = postJournal({ date: today(), memo: 'Reversal of ' + j.no + ': ' + n, lines: j.lines.map(l => ({ acct: l.acct, dr: l.cr, cr: l.dr, dept: l.dept })), source: 'manual', ref: j.id }); DB.set('journals', j.id, { status: 'reversed' }); toast('Reversed as ' + r.no); render(); } catch (e) { toast(e.message, 'bad'); } }); };
let JF = null;
ACT['jv.new'] = () => { JF = { date: today(), memo: '', lines: [{ acct: '', dr: '', cr: '', dept: '' }, { acct: '', dr: '', cr: '', dept: '' }] }; const id = openModal({ title: 'Manual journal', xl: true, live: false, body: jfBody(), foot: '<button class="btn" data-act="ov.close">Cancel</button><button class="btn primary" data-act="jv.submit">Submit for approval</button>' }); OV.stack.find(e => e.id === id).root.addEventListener('input', jfInput); };
function jfBody() {
  const accts = DB.q('accounts').sort(by(a => a.code));
  return `<div class="fgrid"><div class="fld"><label>Journal date</label><input type="date" id="jf-date" value="${JF.date}"></div><div class="fld"><label>Memo</label><input id="jf-memo" value="${esc(JF.memo)}" placeholder="What is this for?"></div></div><table class="tbl" style="margin-top:12px"><thead><tr><th>Account</th><th>Department</th><th class="num">Debit</th><th class="num">Credit</th><th></th></tr></thead><tbody>${JF.lines.map((l, i) => `<tr><td><select data-jf="acct" data-i="${i}" style="width:100%;border:1px solid #C6D8C4;border-radius:10px;padding:8px">${opts(accts.map(a => [a.code, a.code + ' · ' + a.name]), l.acct, 'Select account')}</select></td><td><select data-jf="dept" data-i="${i}" style="border:1px solid #C6D8C4;border-radius:10px;padding:8px">${opts(DB.q('depts').map(d => d.name), l.dept, '—')}</select></td><td><input type="number" data-jf="dr" data-i="${i}" value="${l.dr}" min="0" style="width:130px;text-align:right;border:1px solid #C6D8C4;border-radius:10px;padding:8px"></td><td><input type="number" data-jf="cr" data-i="${i}" value="${l.cr}" min="0" style="width:130px;text-align:right;border:1px solid #C6D8C4;border-radius:10px;padding:8px"></td><td><button class="btn sm ghost" data-act="jv.del" data-i="${i}" aria-label="Remove line">${icon('x', 'sm')}</button></td></tr>`).join('')}</tbody></table><div class="row" style="margin-top:10px"><button class="btn sm" data-act="jv.add">${icon('plus', 'sm')} Add line</button><span class="sp"></span><span id="jf-bal"></span></div><p class="small muted" style="margin-top:8px">Manual journals need approval from a different officer before they post${'' }.</p>`;
}
function jfTotals() { const dr = sum(JF.lines, l => l.dr), cr = sum(JF.lines, l => l.cr); const el = $('#jf-bal'); if (el) el.innerHTML = Math.abs(dr - cr) < .01 && dr > 0 ? `<span class="pill ok">Balanced · ${money(dr)}</span>` : `<span class="pill warn">Out of balance by ${money(Math.abs(dr - cr))} (Dr ${money(dr)} · Cr ${money(cr)})</span>`; }
function jfInput(e) { const t = e.target; if (t.id === 'jf-date') JF.date = t.value; else if (t.id === 'jf-memo') JF.memo = t.value; else if (t.dataset.jf) { JF.lines[+t.dataset.i][t.dataset.jf] = t.dataset.jf === 'dr' || t.dataset.jf === 'cr' ? t.value : t.value; } jfTotals(); }
const jfRepaint = () => { const e = OV.stack[OV.stack.length - 1]; paintOverlay(e, { title: 'Manual journal', body: jfBody(), foot: '<button class="btn" data-act="ov.close">Cancel</button><button class="btn primary" data-act="jv.submit">Submit for approval</button>' }); jfTotals(); };
ACT['jv.add'] = () => { JF.lines.push({ acct: '', dr: '', cr: '', dept: '' }); jfRepaint(); };
ACT['jv.del'] = el => { if (JF.lines.length > 2) JF.lines.splice(+el.dataset.i, 1); jfRepaint(); };
setTimeout(() => document.addEventListener('change', e => { if (e.target.dataset && e.target.dataset.jf && JF) jfInput(e); }), 0);
ACT['jv.submit'] = () => {
  const lines = JF.lines.filter(l => l.acct && (+l.dr || +l.cr)).map(l => ({ acct: l.acct, dr: +l.dr || 0, cr: +l.cr || 0, dept: l.dept }));
  if (!JF.memo.trim()) return toast('Add a memo so approvers know what this is for.', 'warn'); if (lines.length < 2) return toast('A journal needs at least two lines.', 'warn');
  const dr = sum(lines, l => l.dr), cr = sum(lines, l => l.cr); if (Math.abs(dr - cr) > .01) return toast('Debits and credits must be equal before you submit.', 'bad'); if (periodClosed(JF.date)) return toast(monthLabel(monthKey(JF.date)) + ' is closed. Use a date in an open period.', 'bad');
  try { const j = postJournal({ date: JF.date, memo: JF.memo, lines, source: 'manual', status: 'pending' }); startApproval({ type: 'journal', ref: j.id, title: j.no + ' · ' + JF.memo, amount: dr, meta: { link: '#/accounting/journals?j=' + j.id } }); closeOverlay(); toast('Submitted for approval'); render(); } catch (e) { toast(e.message, 'bad'); }
};

/* ---------- payables & receivables ---------- */
function accPayables() {
  const bills = () => DB.q('bills').map(b => ({ ...b, vendor: DB.get('vendors', b.vendorId)?.name || '', net: b.amount + b.vat - (b.whtAmt || 0) }));
  const unpaidInv = DB.q('invoices').filter(i => i.status === 'sent'); const t = today();
  const bk = [0, 0, 0, 0]; unpaidInv.forEach(i => { const d = Math.max(0, daysBetween(i.due, t)); bk[d <= 30 ? 0 : d <= 60 ? 1 : d <= 90 ? 2 : 3] += i.total; });
  return `<div class="grid g3" style="margin-bottom:16px">${tile({ ic: 'wallet', title: 'Payable to vendors', value: moneyShort(sum(DB.q('bills').filter(b => b.status !== 'paid'), b => b.amount + b.vat - (b.whtAmt || 0))), sub: DB.q('bills').filter(b => b.status !== 'paid').length + ' open bills' })}${tile({ cls: 'tea', ic: 'receipt', title: 'Receivable (other income)', value: moneyShort(sum(unpaidInv, i => i.total)), sub: unpaidInv.length + ' invoices · ' + moneyShort(bk[1] + bk[2] + bk[3]) + ' overdue' })}${tile({ cls: 'dark', ic: 'users', title: 'Vendors', value: DB.q('vendors').length })}</div>` +
    table({ id: 'bills', title: 'Vendor bills', rows: bills, ph: 'Search bills or vendors', sort: { k: 'due', dir: 1 }, filters: [{ k: 'status', l: 'Status', o: ['draft', 'approved', 'paid'], get: b => b.status }], tools: accW() ? `<button class="btn sm" data-act="vendor.new">New vendor</button><button class="btn sm primary" data-act="bill.new">${icon('plus', 'sm')} New bill</button>` : '', onRow: b => b.status !== 'paid' && accW() ? openBill(b.id) : null, cols: [{ k: 'no', l: 'Bill', r: b => `<div class="cellmain"><b>${esc(b.no)}</b><span>${esc(b.vendor)}</span></div>`, x: b => b.no + ' ' + b.vendor }, { k: 'desc', l: 'Description' }, { k: 'due', l: 'Due', r: b => fmtDate(b.due), sv: b => b.due }, { k: 'amount', l: 'Amount', num: true, r: b => money(b.amount) }, { k: 'vat', l: 'VAT', num: true, r: b => money(b.vat) }, { k: 'whtAmt', l: 'WHT', num: true, r: b => b.whtAmt ? money(b.whtAmt) : '—' }, { k: 'net', l: 'Net payable', num: true, r: b => money(b.net) }, { k: 'status', l: 'Status', r: b => spill(b.status === 'approved' && b.due < t ? 'Overdue' : b.status), x: b => b.status }] }) +
    `<div style="margin-top:16px">${table({ id: 'vendors', title: 'Vendors', rows: () => DB.q('vendors'), cols: [{ k: 'name', l: 'Vendor' }, { k: 'email', l: 'Email' }, { k: 'phone', l: 'Phone' }, { k: 'terms', l: 'Terms' }, { k: 'tin', l: 'TIN' }, { k: 'wht', l: 'WHT', r: v => v.wht ? 'Applies' : '—', x: v => v.wht ? 'Yes' : 'No' }] })}</div>`;
}
ACT['vendor.new'] = () => openForm({ title: 'New vendor', fields: [{ n: 'name', l: 'Vendor name', req: true }, { n: 'email', l: 'Email', t: 'email', half: true }, { n: 'phone', l: 'Phone', t: 'tel', half: true }, { n: 'terms', l: 'Payment terms', t: 'select', blank: false, o: ['Net 7', 'Net 14', 'Net 30', 'On delivery'], half: true }, { n: 'tin', l: 'Tax ID (TIN)', half: true }, { n: 'wht', l: 'Withholding tax applies', t: 'check' }], onSubmit: v => { DB.add('vendors', v); render(); } });
ACT['bill.new'] = () => openForm({ title: 'New vendor bill', fields: [{ n: 'vendorId', l: 'Vendor', t: 'select', req: true, o: DB.q('vendors').map(v => [v.id, v.name]) }, { n: 'desc', l: 'Description', req: true }, { n: 'cat', l: 'Expense account', t: 'select', req: true, o: DB.q('accounts').filter(a => a.type === 'expense').map(a => [a.code, a.code + ' · ' + a.name]), half: true }, { n: 'amount', l: 'Amount before VAT (₦)', t: 'money', req: true, min: 1, half: true }, { n: 'date', l: 'Bill date', t: 'date', req: true, half: true, v: today() }, { n: 'due', l: 'Due date', t: 'date', req: true, half: true, v: addDays(today(), 14) }, { n: 'vatOn', l: 'Add VAT (' + DB.setting('vatRate') + '%)', t: 'check', v: true }], onSubmit: v => { const ven = DB.get('vendors', v.vendorId); const b = DB.add('bills', { vendorId: v.vendorId, no: 'BL-' + String(DB.seq('bill')).padStart(4, '0'), desc: v.desc, amount: v.amount, vat: v.vatOn ? Math.round(v.amount * DB.setting('vatRate') / 100) : 0, whtAmt: ven.wht ? Math.round(v.amount * DB.setting('whtRate') / 100) : 0, date: v.date, due: v.due, status: 'draft', cat: v.cat }); toast('Bill saved. Another officer must approve it.'); render(); } });
function openBill(id) {
  openDrawer(() => { const b = DB.get('bills', id); if (!b) return null; const v = DB.get('vendors', b.vendorId); const own = b.cby === SESS.uid;
    return { title: esc(b.no) + ' · ' + esc(v?.name), body: `${spill(b.status)}${kv([['Description', esc(b.desc)], ['Amount', money(b.amount)], ['VAT', money(b.vat)], ['WHT deducted', money(b.whtAmt || 0)], ['Net payable', `<b>${money(b.amount + b.vat - (b.whtAmt || 0))}</b>`], ['Due', fmtDate(b.due)], ['Expense account', esc(acctLabel(b.cat))]])}`, foot: b.status === 'draft' ? (own ? '<span class="small muted">You entered this bill, so another officer approves it.</span>' : `<button class="btn primary" data-act="bill.approve" data-id="${id}">Approve and post</button>`) : b.status === 'approved' ? `<button class="btn primary" data-act="bill.pay" data-id="${id}">Pay now</button>` : '<button class="btn" data-act="ov.close">Close</button>' };
  });
}
ACT['bill.approve'] = el => { const b = DB.get('bills', el.dataset.id); if (b.cby === SESS.uid) return toast('You entered this bill, so someone else must approve it.', 'bad'); try { postJournal({ date: b.date > today() ? today() : b.date, memo: 'Bill ' + b.no + ' · ' + DB.get('vendors', b.vendorId).name, lines: [{ acct: b.cat, dr: b.amount }, ...(b.vat ? [{ acct: '1200', dr: b.vat }] : []), { acct: '2000', cr: b.amount + b.vat - (b.whtAmt || 0) }, ...(b.whtAmt ? [{ acct: '2310', cr: b.whtAmt }] : [])], source: 'bill', ref: b.id, quiet: true }); DB.set('bills', b.id, { status: 'approved', approvedBy: SESS.uid }, { action: 'approve' }); toast('Approved and posted to payables'); render(); } catch (e) { toast(e.message, 'bad'); } };
ACT['bill.pay'] = el => { const b = DB.get('bills', el.dataset.id); try { const n = b.amount + b.vat - (b.whtAmt || 0); postJournal({ date: today(), memo: 'Payment of ' + b.no, lines: [{ acct: '2000', dr: n }, { acct: '1010', cr: n }], source: 'bill-pay', ref: b.id, quiet: true }); DB.set('bills', b.id, { status: 'paid', paidAt: Date.now() }, { action: 'pay' }); toast('Payment posted'); closeAllOverlays(); render(); } catch (e) { toast(e.message, 'bad'); } };

/* ---------- bank ---------- */
function bankSuggest(t) { const used = new Set(DB.q('bankTxns').map(x => x.matched).filter(Boolean)); return DB.q('journals').filter(j => j.status === 'posted' && !used.has(j.id) && j.lines.some(l => l.acct === '1010' && Math.abs((l.dr ? l.dr : -l.cr) - t.amount) < 0.5) && Math.abs(daysBetween(j.date, t.date)) <= 7)[0]; }
function accBank() {
  const accts = DB.q('bankAccts'); const txns = DB.q('bankTxns'); const gl = acctBal('1010'); const stmt = sum(txns, t => t.amount);
  const rows = () => DB.q('bankTxns').map(t => ({ ...t, sug: t.matched ? null : bankSuggest(t) }));
  const baTable = table({ id: 'bankaccts', title: 'Bank accounts', rows: () => accts.map(a => { const tx = DB.q('bankTxns').filter(t => t.acct === a.id); return { ...a, lines: tx.length, stmt: sum(tx, t => t.amount), un: tx.filter(t => !t.matched).length }; }), export: false, tools: accW() ? `<button class="btn sm primary" data-act="bankacct.new">${icon('plus', 'sm')} Add bank account</button>` : '', cols: [{ k: 'name', l: 'Account' }, { k: 'bank', l: 'Bank' }, { k: 'acctNo', l: 'Number' }, { k: 'gl', l: 'Ledger account', r: a => esc(acctLabel(a.gl || '1010')), x: a => a.gl }, { k: 'lines', l: 'Statement lines', num: true }, { k: 'un', l: 'To reconcile', num: true }] });
  return `<div style="margin-bottom:16px">${baTable}</div><div class="grid g3" style="margin-bottom:16px">${tile({ ic: 'wallet', title: 'Ledger balance (1010)', value: moneyShort(gl) })}${tile({ cls: 'tea', ic: 'check', title: 'Matched lines', value: txns.filter(t => t.matched).length, unit: '/ ' + txns.length, caps: { v: txns.filter(t => t.matched).length, max: txns.length || 1 } })}${tile({ cls: 'dark', ic: 'warn', title: 'To reconcile', value: txns.filter(t => !t.matched).length, sub: 'Suggested matches below' })}</div><div class="row wrap" style="margin-bottom:12px"><span class="sp"></span>${accW() ? `<button class="btn" data-act="bank.import">${icon('upload', 'sm')} Import statement (CSV or Excel export)</button>` : ''}</div>` + table({ id: 'bank', title: 'Bank statement lines', rows, ph: 'Search description', sort: { k: 'date', dir: -1 }, filters: [{ k: 'm', l: 'Match', o: [['yes', 'Matched'], ['no', 'Unmatched']], get: t => t.matched ? 'yes' : 'no' }], cols: [{ k: 'date', l: 'Date', r: t => fmtDate(t.date), sv: t => t.date }, { k: 'desc', l: 'Description' }, { k: 'amount', l: 'Amount', num: true, r: t => `<span style="color:${t.amount < 0 ? 'var(--err)' : 'inherit'}">${money(t.amount)}</span>` }, { k: 'matched', l: 'Reconciliation', r: t => t.matched ? spill('Matched', 'ok') + `<div class="small muted">${esc(DB.get('journals', t.matched)?.no || '')}</div>` : t.sug ? `<span class="small">Suggested: <b style="font-weight:500">${esc(t.sug.no)}</b> ${esc(t.sug.memo.slice(0, 30))}</span>` : spill('Unmatched', 'warn'), x: t => t.matched ? 'Matched' : 'Unmatched' }, { k: 'a', l: '', r: t => accW() ? (t.matched ? `<button class="btn sm ghost" data-act="bank.unmatch" data-id="${t.id}">Unmatch</button>` : t.sug ? `<button class="btn sm primary" data-act="bank.accept" data-id="${t.id}" data-j="${t.sug.id}">Accept</button>` : `<button class="btn sm" data-act="bank.entry" data-id="${t.id}">Create entry</button>`) : '', x: () => '' }] });
}
ACT['bank.accept'] = el => { DB.set('bankTxns', el.dataset.id, { matched: el.dataset.j }, { action: 'match' }); render(); };
ACT['bank.unmatch'] = el => { DB.set('bankTxns', el.dataset.id, { matched: '' }, { action: 'unmatch' }); render(); };
ACT['bank.entry'] = el => { const t = DB.get('bankTxns', el.dataset.id); const out = t.amount < 0; openForm({ title: 'Create entry for bank line', fields: [{ n: 'acct', l: out ? 'Expense account' : 'Income account', t: 'select', req: true, o: DB.q('accounts').filter(a => out ? a.type === 'expense' : ['income', 'liability', 'asset'].includes(a.type) && a.code !== '1010').map(a => [a.code, a.code + ' · ' + a.name]), v: out ? '5950' : '4200' }, { n: 'memo', l: 'Memo', req: true, v: t.desc }], onSubmit: v => { try { const a = Math.abs(t.amount); const j = postJournal({ date: t.date > today() ? today() : t.date, memo: v.memo, lines: out ? [{ acct: v.acct, dr: a }, { acct: '1010', cr: a }] : [{ acct: '1010', dr: a }, { acct: v.acct, cr: a }], source: 'manual', ref: t.id, quiet: true }); DB.set('bankTxns', t.id, { matched: j.id }); toast('Entry posted and matched'); render(); } catch (e) { toast(e.message, 'bad'); return false; } } }); };
ACT['bank.import'] = () => importDialog({ title: 'Import bank statement', cols: ['date', 'description', 'amount'], example: '2026-10-12,NIP/Client transfer,350000', validate: r => { const d = r.date || r.Date; const a = parseFloat(String(r.amount || r.Amount || '').replace(/,/g, '')); if (!/^\d{4}-\d{2}-\d{2}$/.test(d || '')) return { err: 'Date must be YYYY-MM-DD' }; if (isNaN(a)) return { err: 'Amount is not a number' }; const dup = DB.q('bankTxns').find(t => t.date === d && t.amount === a && t.desc === (r.description || r.Description)); if (dup) return { err: 'Already imported' }; return { rec: { acct: DB.q('bankAccts')[0]?.id, date: d, desc: r.description || r.Description || '', amount: a, matched: '' } }; }, commit: recs => recs.forEach(r => DB.add('bankTxns', r, { quiet: true })) });

/* ---------- statements ---------- */
function stmtRange() { const fy = fiscalYear(); const sel = UI.stmtRange || 'fytd'; if (sel === 'fytd') return { from: fy.start, to: today(), l: fy.label + ' to date' }; if (sel === 'lastfy') { const p = fiscalYear(addDays(fy.start, -1)); return { from: p.start, to: p.end, l: p.label }; } if (sel === 'month') { const m = monthKey(today()); return { from: m + '-01', to: m + '-31', l: monthLabel(m) }; } const m = monthKey(addMonths(today(), -1)); return { from: m + '-01', to: m + '-31', l: monthLabel(m) }; }
function consolidated(fn) { const keep = CO; const parts = {}; try { DB.d.companies.forEach(c => { CO = c.id; fn(c, parts); }); } finally { CO = keep; } return parts; }
function accStatements(sub) {
  const r = stmtRange(); const st = [{ k: 'pnl', l: 'Profit and loss' }, { k: 'bs', l: 'Balance sheet' }, { k: 'tb', l: 'Trial balance' }, { k: 'cf', l: 'Cash flow' }]; const group = UI.stmtGroup && can('multi.co');
  let tbRows = group ? Object.values(consolidated((c, p) => trialBalance(r.from, r.to).forEach(a => { const x = p[a.code] = p[a.code] || { ...a, dr: 0, cr: 0 }; x.dr += a.dr; x.cr += a.cr; }))).map(a => ({ ...a, bal: ['asset', 'expense'].includes(a.type) ? a.dr - a.cr : a.cr - a.dr })).sort(by(a => a.code)) : trialBalance(r.from, r.to);
  const inc = tbRows.filter(a => a.type === 'income' && a.bal), exp = tbRows.filter(a => a.type === 'expense' && a.bal); const ti = sum(inc, a => a.bal), te = sum(exp, a => a.bal);
  const head = `<div class="row wrap" style="margin-bottom:14px"><label class="chip"><select data-on="stmt.range" aria-label="Period">${opts([['fytd', fiscalYear().label + ' to date'], ['lastfy', 'Last financial year'], ['month', 'This month'], ['lastmonth', 'Last month']], UI.stmtRange || 'fytd')}</select></label>${can('multi.co') ? `<label class="chip"><input type="checkbox" data-on="stmt.group" ${group ? 'checked' : ''}> Group consolidation (all companies)</label>` : ''}<span class="sp"></span>${exportBtn('Trial balance ' + r.l, [{ l: 'Code', x: a => a.code }, { l: 'Account', x: a => a.name }, { l: 'Debit', x: a => a.dr }, { l: 'Credit', x: a => a.cr }, { l: 'Balance', x: a => a.bal }], () => tbRows.filter(a => a.dr || a.cr))}</div><nav class="tabs">${st.map(s => `<a href="#/accounting/statements/${s.k}" class="${sub === s.k ? 'on' : ''}">${s.l}</a>`).join('')}</nav>`;
  const cap = `<p class="small muted" style="margin-bottom:10px">${esc(group ? 'Group (consolidated)' : company().name)} · ${esc(r.l)}</p>`; const line = (l, v, b) => `<tr><td ${b ? 'style="font-weight:500"' : ''}>${esc(l)}</td><td class="num" ${b ? 'style="font-weight:500"' : ''}>${money(v)}</td></tr>`;
  let body = '';
  if (sub === 'pnl') body = `<div class="card white">${cap}<table class="tbl"><tbody><tr><th colspan="2">Income</th></tr>${inc.map(a => line(a.code + ' · ' + a.name, a.bal)).join('')}${line('Total income', ti, 1)}<tr><th colspan="2">Expenses</th></tr>${exp.map(a => line(a.code + ' · ' + a.name, a.bal)).join('')}${line('Total expenses', te, 1)}<tr><th>Net profit</th><th class="num" style="color:${ti - te < 0 ? 'var(--err)' : 'var(--deep)'}">${money(ti - te)}</th></tr></tbody></table></div>`;
  else if (sub === 'bs') { const all = group ? Object.values(consolidated((c, p) => trialBalance(null, today()).forEach(a => { const x = p[a.code] = p[a.code] || { ...a, dr: 0, cr: 0 }; x.dr += a.dr; x.cr += a.cr; }))).map(a => ({ ...a, bal: ['asset', 'expense'].includes(a.type) ? a.dr - a.cr : a.cr - a.dr })) : trialBalance(null, today()); const A = all.filter(a => a.type === 'asset' && a.bal), L = all.filter(a => a.type === 'liability' && a.bal), E = all.filter(a => a.type === 'equity' && a.bal); const earn = sum(all.filter(a => a.type === 'income'), a => a.bal) - sum(all.filter(a => a.type === 'expense'), a => a.bal); body = `<div class="card white"><p class="small muted" style="margin-bottom:10px">As at ${fmtDate(today())}</p><table class="tbl"><tbody><tr><th colspan="2">Assets</th></tr>${A.map(a => line(a.code + ' · ' + a.name, a.bal)).join('')}${line('Total assets', sum(A, a => a.bal), 1)}<tr><th colspan="2">Liabilities</th></tr>${L.map(a => line(a.code + ' · ' + a.name, a.bal)).join('')}${line('Total liabilities', sum(L, a => a.bal), 1)}<tr><th colspan="2">Equity</th></tr>${E.map(a => line(a.code + ' · ' + a.name, a.bal)).join('')}${line('Profit for the period (all time)', earn)}${line('Total equity', sum(E, a => a.bal) + earn, 1)}<tr><th>Liabilities + equity</th><th class="num">${money(sum(L, a => a.bal) + sum(E, a => a.bal) + earn)}</th></tr></tbody></table>${Math.abs(sum(A, a => a.bal) - (sum(L, a => a.bal) + sum(E, a => a.bal) + earn)) < 1 ? '<div class="alert ok" style="margin-top:12px">Balanced: assets equal liabilities plus equity.</div>' : '<div class="alert bad" style="margin-top:12px">Balance sheet does not balance. Run the integrity check in Admin.</div>'}</div>`; }
  else if (sub === 'tb') { const rows = tbRows.filter(a => a.dr || a.cr); body = `<div class="card white">${cap}<table class="tbl"><thead><tr><th>Code</th><th>Account</th><th class="num">Debit</th><th class="num">Credit</th></tr></thead><tbody>${rows.map(a => `<tr><td>${a.code}</td><td>${esc(a.name)}</td><td class="num">${a.dr ? money(a.dr) : ''}</td><td class="num">${a.cr ? money(a.cr) : ''}</td></tr>`).join('')}<tr><th colspan="2">Totals</th><th class="num">${money(sum(rows, a => a.dr))}</th><th class="num">${money(sum(rows, a => a.cr))}</th></tr></tbody></table></div>`; }
  else { const cats = { 'Receipts from clients': ['payment', 'invoice-pay'], 'Payments to suppliers': ['bill-pay', 'expense-pay'], 'Commissions paid': ['commission-paid'], 'Salaries and payroll': ['payroll'], 'Refunds': ['refund'], 'Asset purchases': ['asset'], 'Capital introduced': ['capital'], 'Tax remittances': ['tax'] }; const flows = {}; DB.q('journals').filter(j => j.status === 'posted').forEach(j => { const d = j.lines.filter(l => ['1010', '1020'].includes(l.acct)).reduce((s, l) => s + l.dr - l.cr, 0); if (!d) return; const inR = j.date >= r.from && j.date <= r.to; const k = Object.keys(cats).find(c => cats[c].includes(j.source)) || (j.memo.startsWith('Opening capital') ? 'Capital introduced' : 'Other operating'); flows[k] = flows[k] || { in: 0, before: 0 }; if (inR) flows[k].in += d; else if (j.date < r.from) flows[k].before += d; }); const open = sum(Object.values(flows), f => f.before), net = sum(Object.values(flows), f => f.in); body = `<div class="card white">${cap}<table class="tbl"><tbody>${line('Opening cash and bank', open, 1)}${Object.entries(flows).filter(([k, f]) => f.in).map(([k, f]) => line(k, f.in)).join('')}${line('Net cash movement', net, 1)}<tr><th>Closing cash and bank</th><th class="num">${money(open + net)}</th></tr></tbody></table></div>`; }
  return head + body;
}
ACT['stmt.range'] = el => { UI.stmtRange = el.value; render(); };
ACT['stmt.group'] = el => { UI.stmtGroup = el.checked; render(); };

/* ---------- period close ---------- */
function periodChecks(id) {
  const inM = d => d && monthKey(d) === id;
  const unconf = DB.q('payments').filter(p => ['pending', 'awaiting second'].includes(p.status) && inM(p.date)).length; const pj = DB.q('journals').filter(j => j.status === 'pending' && inM(j.date)).length; const unm = DB.q('bankTxns').filter(t => !t.matched && inM(t.date)).length; const dep = !DB.q('assets').length || DB.q('journals').some(j => j.source === 'depr' && j.ref === id);
  return [{ k: 'pay', l: 'All client payments for the month are confirmed or rejected', ok: unconf === 0, auto: true, d: unconf + ' pending' }, { k: 'jv', l: 'No manual journals awaiting approval', ok: pj === 0, auto: true, d: pj + ' pending' }, { k: 'bank', l: 'Bank lines for the month are reconciled', ok: unm === 0, auto: true, d: unm + ' unmatched' }, { k: 'depr', l: 'Depreciation posted', ok: dep, auto: true, d: dep ? 'Posted' : 'Not posted' }, { k: 'accr', l: 'Accruals and prepayments reviewed', manual: true }, { k: 'recv', l: 'Receivables and collections reviewed', manual: true }];
}
function accPeriods() {
  const ps = DB.q('periods').sort(by(p => p.id, -1));
  return `<div class="alert info" style="margin-bottom:14px">${icon('lock', 'sm')}<span>Closing a month locks it: nothing can post with a date inside a closed period. Only an executive can reopen it, and the reopen is logged.</span></div>` + table({ id: 'periods', title: 'Periods', rows: () => ps, export: false, cols: [{ k: 'id', l: 'Period', r: p => monthLabel(p.id), x: p => p.id }, { k: 'status', l: 'Status', r: p => spill(p.status === 'closed' ? 'Closed' : 'Open', p.status === 'closed' ? 'dark' : 'ok') }, { k: 'closedAt', l: 'Closed', r: p => p.closedAt ? fmtDate(isoDate(p.closedAt)) + ' · ' + esc(userName(p.closedBy)) : '—' }, { k: 'ro', l: 'Reopened', r: p => (p.reopened || []).length ? (p.reopened.length + '×') : '—' }, { k: 'a', l: '', r: p => p.status === 'open' ? (can('acc.close') ? `<button class="btn sm primary" data-act="per.close" data-id="${p.id}">Month-end checklist</button>` : '') : (can('period.reopen') ? `<button class="btn sm" data-act="per.reopen" data-id="${p.id}">Reopen</button>` : can('acc.close') ? `<button class="btn sm" data-act="per.request" data-id="${p.id}">Request reopen</button>` : ''), x: () => '' }] });
}
ACT['per.close'] = el => {
  const id = el.dataset.id; openDrawer(() => { const p = DB.get('periods', id); const chk = periodChecks(id); const man = p.checklist || {}; const ready = chk.every(c => c.auto ? c.ok : man[c.k]);
    return { title: 'Close ' + monthLabel(id), body: `<div class="stack" style="gap:10px">${chk.map(c => `<label class="row" style="gap:10px;align-items:flex-start">${c.auto ? (c.ok ? icon('check') : icon('warn')) : `<input type="checkbox" data-act="per.tick" data-id="${id}" data-k="${c.k}" ${man[c.k] ? 'checked' : ''}>`}<span class="grow">${esc(c.l)}${c.auto ? `<br><span class="small ${c.ok ? 'muted' : ''}" style="${c.ok ? '' : 'color:var(--harvest)'}">${esc(c.d)}</span>` : ''}</span></label>`).join('')}</div>${ready ? '<div class="alert ok" style="margin-top:16px">Ready to close.</div>' : '<div class="alert" style="margin-top:16px">Complete every item to close the period.</div>'}`, foot: `<button class="btn" data-act="ov.close">Cancel</button><button class="btn primary" ${ready ? '' : 'disabled'} data-act="per.lock" data-id="${id}">${icon('lock', 'sm')} Close and lock period</button>` };
  });
};
ACT['per.tick'] = el => { const p = DB.get('periods', el.dataset.id); DB.set('periods', p.id, { checklist: { ...(p.checklist || {}), [el.dataset.k]: el.checked } }, { quiet: true }); refreshOverlays(); };
ACT['per.lock'] = el => { DB.set('periods', el.dataset.id, { status: 'closed', closedAt: Date.now(), closedBy: SESS.uid }, { action: 'period-close' }); closeAllOverlays(); toast(monthLabel(el.dataset.id) + ' is closed'); render(); };
ACT['per.reopen'] = el => askText('Reopen ' + monthLabel(el.dataset.id), 'Reason (logged permanently)', n => { const p = DB.get('periods', el.dataset.id); DB.set('periods', p.id, { status: 'open', reopened: (p.reopened || []).concat([{ ts: Date.now(), by: SESS.uid, reason: n }]) }, { action: 'period-reopen' }); toast('Period reopened and logged'); render(); }, { submit: 'Reopen period' });
ACT['per.request'] = el => askText('Request reopen of ' + monthLabel(el.dataset.id), 'Why does it need reopening?', n => { startApproval({ type: 'reopen', ref: el.dataset.id, title: 'Reopen ' + monthLabel(el.dataset.id), meta: { reason: n, link: '#/accounting/periods' } }); toast('Request sent to an executive'); render(); });

/* ---------- tax (ACC-06) ---------- */
function accTax() {
  const months = Stat.months(4).reverse(); const rowsV = months.map(m => { const out = sum(DB.q('invoices').filter(i => ['sent', 'paid'].includes(i.status) && monthKey(i.issued) === m), i => i.vat); const inn = sum(DB.q('bills').filter(b => monthKey(b.date) === m), b => b.vat); const wht = sum(DB.q('bills').filter(b => monthKey(b.date) === m), b => b.whtAmt || 0); return { id: m, m, out, inn, net: out - inn, wht }; });
  const taxes = () => DB.q('taxes').map(t => ({ ...t }));
  return `<div class="alert info" style="margin-bottom:14px">${icon('receipt', 'sm')}<span>VAT ${DB.setting('vatRate')}% and withholding tax ${DB.setting('whtRate')}% are computed from invoices and vendor bills. Remit by the 21st of the following month.</span></div>` + table({ id: 'vat', title: 'VAT and WHT by month', rows: () => rowsV, export: true, cols: [{ k: 'm', l: 'Month', r: r => monthLabel(r.m), x: r => r.m }, { k: 'out', l: 'Output VAT', num: true, r: r => money(r.out) }, { k: 'inn', l: 'Input VAT', num: true, r: r => money(r.inn) }, { k: 'net', l: 'Net VAT payable', num: true, r: r => money(r.net) }, { k: 'wht', l: 'WHT deducted', num: true, r: r => money(r.wht) }, { k: 'a', l: '', r: r => accW() ? `<button class="btn sm" data-act="tax.compute" data-m="${r.m}">Add to remittances</button>` : '', x: () => '' }] }) +
    `<div style="margin-top:16px">${table({ id: 'taxes', title: 'Statutory remittances', rows: taxes, empty: 'No remittances tracked yet.', sort: { k: 'period', dir: -1 }, cols: [{ k: 'type', l: 'Tax', r: t => `<b style="font-weight:500">${esc(t.type)}</b>` }, { k: 'period', l: 'Period', r: t => monthLabel(t.period), x: t => t.period }, { k: 'amount', l: 'Amount', num: true, r: t => money(t.amount) }, { k: 'due', l: 'Due', r: t => fmtDate(t.due) }, { k: 'status', l: 'Status', r: t => spill(t.status === 'Pending' && t.due < today() ? 'Overdue' : t.status), x: t => t.status }, { k: 'a', l: '', r: t => t.status === 'Pending' && accW() ? `<button class="btn sm primary" data-act="tax.remit" data-id="${t.id}">Mark remitted</button>` : '', x: () => '' }] })}</div>`;
}
ACT['tax.compute'] = el => { const m = el.dataset.m; const out = sum(DB.q('invoices').filter(i => ['sent', 'paid'].includes(i.status) && monthKey(i.issued) === m), i => i.vat), inn = sum(DB.q('bills').filter(b => monthKey(b.date) === m), b => b.vat), wht = sum(DB.q('bills').filter(b => monthKey(b.date) === m), b => b.whtAmt || 0); const due = addMonths(m + '-01', 1).slice(0, 8) + '21'; if (!DB.q('taxes').some(t => t.type === 'VAT' && t.period === m) && out - inn > 0) DB.add('taxes', { type: 'VAT', period: m, amount: out - inn, out, inn, status: 'Pending', due }); if (!DB.q('taxes').some(t => t.type === 'WHT' && t.period === m) && wht > 0) DB.add('taxes', { type: 'WHT', period: m, amount: wht, status: 'Pending', due }); toast('Remittances updated'); render(); };
ACT['tax.remit'] = el => { const t = DB.get('taxes', el.dataset.id); try { const lines = t.type === 'VAT' ? [{ acct: '2300', dr: Math.max(t.out || t.amount, t.amount) }, { acct: '1200', cr: (t.inn || 0) }, { acct: '1010', cr: t.amount }].filter(l => l.dr || l.cr) : [{ acct: '2310', dr: t.amount }, { acct: '1010', cr: t.amount }]; if (t.type === 'VAT') { const out = t.out || t.amount; lines.length = 0; lines.push({ acct: '2300', dr: out }, ...(t.inn ? [{ acct: '1200', cr: t.inn }] : []), { acct: '1010', cr: out - (t.inn || 0) }); } postJournal({ date: today(), memo: t.type + ' remittance ' + monthLabel(t.period), lines, source: 'tax', ref: t.id, quiet: true }); DB.set('taxes', t.id, { status: 'Remitted', remittedAt: Date.now() }, { action: 'remit' }); toast('Remittance posted'); render(); } catch (e) { toast(e.message, 'bad'); } };

/* ---------- fixed assets (ACC-08, OPS-14) ---------- */
const assetDep = a => Math.round(a.cost / (a.life * 12)); const assetAcc = a => Math.min(a.cost, assetDep(a) * Math.max(0, Math.floor(daysBetween(a.acquired, a.depTo || today()) / 30.4)));
function accAssets() {
  const rows = () => DB.q('assets').map(a => ({ ...a, dep: assetDep(a), acc: assetAcc(a), nbv: a.cost - assetAcc(a), holder: a.assignedTo ? userName(a.assignedTo) : '' }));
  const mk = monthKey(today());
  return `<div class="grid g3" style="margin-bottom:16px">${tile({ ic: 'layers', title: 'Cost', value: moneyShort(sum(DB.q('assets'), a => a.cost)), sub: DB.q('assets').length + ' assets' })}${tile({ cls: 'tea', ic: 'trend', title: 'Net book value', value: moneyShort(sum(rows(), a => a.nbv)) })}${tile({ cls: 'dark', ic: 'calendar', title: 'Monthly depreciation', value: moneyShort(sum(DB.q('assets'), assetDep)), sub: DB.q('journals').some(j => j.source === 'depr' && j.ref === mk) ? 'Posted for ' + monthLabel(mk) : 'Not yet posted for ' + monthLabel(mk) })}</div>` + table({ id: 'assets', title: 'Fixed asset register', rows, ph: 'Search assets', filters: [{ k: 'category', l: 'Category', o: ['Vehicle', 'Equipment', 'Furniture', 'Property', 'Other'], get: a => a.category }], tools: accW() ? `<button class="btn sm" data-act="depr.post">Post ${monthLabel(mk)} depreciation</button><button class="btn sm primary" data-act="asset.new">${icon('plus', 'sm')} Add asset</button>` : '', onRow: a => accW() || can('hr.write') || can('inv.write') ? assignAsset(a.id) : null, cols: [{ k: 'tag', l: 'Tag' }, { k: 'name', l: 'Asset' }, { k: 'category', l: 'Category' }, { k: 'acquired', l: 'Acquired', r: a => fmtDate(a.acquired), sv: a => a.acquired }, { k: 'cost', l: 'Cost', num: true, r: a => money(a.cost) }, { k: 'acc', l: 'Accum. depn', num: true, r: a => money(a.acc) }, { k: 'nbv', l: 'Book value', num: true, r: a => money(a.nbv) }, { k: 'holder', l: 'Assigned to', r: a => esc(a.holder || '—') }] });
}
ACT['asset.new'] = () => openForm({ title: 'Add fixed asset', fields: [{ n: 'name', l: 'Asset', req: true }, { n: 'category', l: 'Category', t: 'select', req: true, o: ['Vehicle', 'Equipment', 'Furniture', 'Property', 'Other'], half: true }, { n: 'cost', l: 'Cost (₦)', t: 'money', req: true, min: 1, half: true }, { n: 'acquired', l: 'Acquired', t: 'date', req: true, v: today(), half: true }, { n: 'life', l: 'Useful life (years)', t: 'number', req: true, min: 1, v: 5, half: true }, { n: 'assignedTo', l: 'Assign to', t: 'select', o: coUsers().map(u => [u.id, u.name]), blank: 'Unassigned' }, { n: 'pay', l: 'Paid from bank (posts Dr fixed assets / Cr bank)', t: 'check', v: true }], onSubmit: v => { try { const a = DB.add('assets', { tag: 'AST-' + String(DB.seq('asset')).padStart(3, '0'), name: v.name, category: v.category, cost: v.cost, life: v.life, acquired: v.acquired, assignedTo: v.assignedTo || '', status: 'In use' }); if (v.pay) postJournal({ date: v.acquired > today() ? today() : v.acquired, memo: 'Purchase of ' + v.name, lines: [{ acct: '1500', dr: v.cost }, { acct: '1010', cr: v.cost }], source: 'asset', ref: a.id, quiet: true }); render(); } catch (e) { toast(e.message, 'bad'); return false; } } });
function assignAsset(id) { const a = DB.get('assets', id); openForm({ title: 'Assign ' + a.name, vals: { assignedTo: a.assignedTo || '', status: a.status }, fields: [{ n: 'assignedTo', l: 'Assigned to', t: 'select', o: coUsers().map(u => [u.id, u.name]), blank: 'Unassigned' }, { n: 'status', l: 'Status', t: 'select', blank: false, o: ['In use', 'In storage', 'Under repair', 'Disposed'] }], onSubmit: v => { DB.set('assets', id, v, { action: 'assign' }); render(); } }); }
ACT['depr.post'] = () => { const m = monthKey(today()); if (DB.q('journals').some(j => j.source === 'depr' && j.ref === m)) return toast('Depreciation for ' + monthLabel(m) + ' is already posted.', 'warn'); const total = sum(DB.q('assets').filter(a => a.status !== 'Disposed'), assetDep); try { postJournal({ date: today(), memo: 'Depreciation ' + monthLabel(m), lines: [{ acct: '5900', dr: total, dept: 'Finance' }, { acct: '1590', cr: total }], source: 'depr', ref: m, quiet: true }); toast('Depreciation posted: ' + money(total)); render(); } catch (e) { toast(e.message, 'bad'); } };

/* ---------- payroll journal (ACC-07) ---------- */
function accPayroll() {
  const rows = () => DB.q('journals').filter(j => j.source === 'payroll').map(j => ({ ...j }));
  return `<div class="alert info" style="margin-bottom:14px">${icon('briefcase', 'sm')}<span>Tri-OP does not run payroll. HR exports payroll inputs (attendance, deductions, allowances) to your payroll provider; when it returns totals, post the payroll journal here.</span></div>` + table({ id: 'payroll', title: 'Payroll journals', rows, empty: 'No payroll journals posted yet.', tools: accW() ? `<button class="btn sm primary" data-act="pay.journal">${icon('plus', 'sm')} Post payroll journal</button>` : '', onRow: j => openJournal(j.id), cols: [{ k: 'date', l: 'Date', r: j => fmtDate(j.date) }, { k: 'memo', l: 'Memo' }, { k: 'total', l: 'Gross', num: true, r: j => money(j.total) }, { k: 'no', l: 'Journal' }] });
}
ACT['pay.journal'] = () => openForm({ title: 'Post payroll journal', fields: [{ n: 'month', l: 'Payroll month', t: 'select', req: true, o: Stat.months(4).map(m => [m, monthLabel(m)]), blank: false, v: monthKey(today()) }, { n: 'gross', l: 'Gross pay (₦)', t: 'money', req: true, min: 1 }, { n: 'paye', l: 'PAYE (₦)', t: 'money', half: true, v: 0 }, { n: 'pension', l: 'Pension (₦)', t: 'money', half: true, v: 0 }, { n: 'nhf', l: 'NHF and other (₦)', t: 'money', half: true, v: 0 }, { n: 'net', t: 'html', html: '<p class="small muted">Net pay is gross less deductions. Statutory remittance itself happens outside Tri-OP.</p>' }], onSubmit: v => { const ded = (v.paye || 0) + (v.pension || 0) + (v.nhf || 0); if (ded > v.gross) { toast('Deductions are more than gross pay.', 'bad'); return false; } try { postJournal({ date: today(), memo: 'Payroll ' + monthLabel(v.month), lines: [{ acct: '5200', dr: v.gross, dept: 'HR' }, ...(ded ? [{ acct: '2400', cr: ded }] : []), { acct: '1010', cr: v.gross - ded }], source: 'payroll', ref: v.month }); toast('Payroll journal posted'); render(); } catch (e) { toast(e.message, 'bad'); return false; } } });

/* ---------- general ledger ---------- */
function accLedger() {
  const code = UI.glAcct || '1010'; const from = UI.glFrom || addMonths(today(), -1), to = UI.glTo || today(); const a = acctByCode(code); const debitNormal = ['asset', 'expense'].includes(a.type);
  let run = 0; DB.q('journals').filter(j => j.status === 'posted' && j.date < from).forEach(j => j.lines.filter(l => l.acct === code).forEach(l => { run += debitNormal ? l.dr - l.cr : l.cr - l.dr; }));
  const open = run; const rows = []; DB.q('journals').filter(j => j.status === 'posted' && j.date >= from && j.date <= to).sort(by(j => j.date + j.no)).forEach(j => j.lines.filter(l => l.acct === code).forEach(l => { run += debitNormal ? l.dr - l.cr : l.cr - l.dr; rows.push({ id: j.id + rows.length, jid: j.id, date: j.date, no: j.no, memo: j.memo, source: j.source, dr: l.dr, cr: l.cr, bal: run }); }));
  const cols = [{ l: 'Date', x: r => r.date }, { l: 'Journal', x: r => r.no }, { l: 'Memo', x: r => r.memo }, { l: 'Debit', x: r => r.dr }, { l: 'Credit', x: r => r.cr }, { l: 'Balance', x: r => r.bal }];
  return `<div class="row wrap" style="margin-bottom:14px"><label class="chip"><select data-on="gl.acct" aria-label="Account">${opts(DB.q('accounts').sort(by(x => x.code)).map(x => [x.code, x.code + ' · ' + x.name]), code)}</select></label><label class="chip"><span class="small muted">From</span><input type="date" value="${from}" data-on="gl.from" aria-label="From"></label><label class="chip"><span class="small muted">To</span><input type="date" value="${to}" data-on="gl.to" aria-label="To"></label><span class="sp"></span>${exportBtn('General ledger ' + code, cols, () => rows)}</div><div class="grid g3" style="margin-bottom:14px">${tile({ ic: 'calc', title: esc(a.name), value: money(run), sub: 'Closing balance at ' + fmtDate(to) })}${tile({ cls: 'tea', ic: 'arrowur', title: 'Opening balance', value: money(open), sub: 'At ' + fmtDate(from) })}${tile({ ic: 'list', title: 'Postings in range', value: rows.length, sub: money(sum(rows, r => r.dr)) + ' Dr · ' + money(sum(rows, r => r.cr)) + ' Cr' })}</div>` + table({ id: 'gl', title: 'General ledger ' + code, rows: () => rows, ps: 15, ph: 'Search memo or journal', empty: 'No postings in this period.', onRow: r => openJournal(r.jid), cols: [{ k: 'date', l: 'Date', r: r => fmtDate(r.date), sv: r => r.date }, { k: 'no', l: 'Journal' }, { k: 'memo', l: 'Memo' }, { k: 'source', l: 'Source', r: r => `<span class="tag">${esc(r.source)}</span>`, x: r => r.source }, { k: 'dr', l: 'Debit', num: true, r: r => r.dr ? money(r.dr) : '' }, { k: 'cr', l: 'Credit', num: true, r: r => r.cr ? money(r.cr) : '' }, { k: 'bal', l: 'Balance', num: true, r: r => money(r.bal) }] });
}
ACT['gl.acct'] = el => { UI.glAcct = el.value; render(); }; ACT['gl.from'] = el => { UI.glFrom = el.value; render(); }; ACT['gl.to'] = el => { UI.glTo = el.value; render(); };

/* ---------- non-property receivables ---------- */
function accReceivables() {
  const t = today(); const rows = () => DB.q('invoices').filter(i => ['sent', 'paid'].includes(i.status)).map(i => { const d = i.status === 'paid' ? 0 : Math.max(0, daysBetween(i.due, t)); return { ...i, days: d, bucket: i.status === 'paid' ? 'Paid' : d === 0 ? 'Current' : d <= 30 ? '1–30' : d <= 60 ? '31–60' : d <= 90 ? '61–90' : '90+', open: i.status === 'paid' ? 0 : i.total }; });
  const r = rows(); const custs = uniq(r.filter(x => x.open).map(x => x.customer)).map(c => ({ l: c, v: sum(r.filter(x => x.customer === c), x => x.open) }));
  return `<div class="grid g4" style="margin-bottom:16px">${['Current', '1–30', '31–60', '61–90'].map((b, i) => tile({ cls: i === 0 ? 'tea' : '', ic: 'receipt', title: b + (i ? ' days late' : ''), value: moneyShort(sum(r.filter(x => x.bucket === b), x => x.open)), sub: r.filter(x => x.bucket === b).length + ' invoices' })).join('')}</div><div class="grid g21" style="align-items:start">${table({ id: 'ar', title: 'Non-property receivables', rows, ph: 'Search customer or invoice', sort: { k: 'days', dir: -1 }, onRow: i => openInvoice(i.id), filters: [{ k: 'bucket', l: 'Aging', o: ['Current', '1–30', '31–60', '61–90', '90+', 'Paid'], get: i => i.bucket }], cols: [{ k: 'no', l: 'Invoice' }, { k: 'customer', l: 'Customer' }, { k: 'due', l: 'Due', r: i => fmtDate(i.due), sv: i => i.due }, { k: 'total', l: 'Amount', num: true, r: i => money(i.total) }, { k: 'open', l: 'Outstanding', num: true, r: i => i.open ? money(i.open) : '—' }, { k: 'bucket', l: 'Aging', r: i => spill(i.bucket, i.bucket === 'Paid' || i.bucket === 'Current' ? 'ok' : 'warn') }] })}${card('Outstanding by customer', custs.length ? hbars(custs.sort(by(x => x.v, -1)), moneyShort) : '<p class="muted">Nothing outstanding.</p>', { ic: 'users' })}</div><p class="small muted" style="margin-top:10px">Property sales receivables are on Finance → Collections and in the Tri-Pay payment plans. This ledger holds facility management, consultancy and rent income.</p>`;
}

/* ---------- group consolidation (ACC-04, P3) ---------- */
function accConsol() {
  if (!can('multi.co')) return card('', emptyState('Group consolidation is available to Group Executives.', 'lock'));
  const r = stmtRange(); const cos = DB.d.companies; const keep = CO; const data = {};
  try { cos.forEach(c => { CO = c.id; const p = pnl(r.from, r.to); const bs = balanceSheet(today()); data[c.id] = { income: p.income, expense: p.expense, net: p.net, assets: bs.tAssets, liab: bs.tLiab, eq: bs.tEq, cash: acctBal('1010') }; }); } finally { CO = keep; }
  const rowsDef = [['Income', 'income'], ['Expenses', 'expense'], ['Net profit', 'net'], ['Cash and bank', 'cash'], ['Total assets', 'assets'], ['Total liabilities', 'liab'], ['Total equity', 'eq']];
  return `<div class="alert info" style="margin-bottom:14px">${icon('building', 'sm')}<span>Companies side by side with a group total for ${esc(r.l)}. Intercompany balances are not eliminated because there are none yet.</span></div><div class="row" style="margin-bottom:12px"><label class="chip"><select data-on="stmt.range" aria-label="Period">${opts([['fytd', fiscalYear().label + ' to date'], ['lastfy', 'Last financial year'], ['month', 'This month'], ['lastmonth', 'Last month']], UI.stmtRange || 'fytd')}</select></label><span class="sp"></span>${exportBtn('Group consolidation ' + r.l, [{ l: 'Line', x: x => x[0] }, ...cos.map(c => ({ l: c.name, x: x => data[c.id][x[1]] })), { l: 'Group', x: x => sum(cos, c => data[c.id][x[1]]) }], () => rowsDef)}</div>${card('Consolidated position', `<table class="tbl"><thead><tr><th></th>${cos.map(c => `<th class="num">${esc(c.short)}</th>`).join('')}<th class="num">Group</th></tr></thead><tbody>${rowsDef.map(([l, k]) => `<tr><td ${['net', 'assets'].includes(k) ? 'style="font-weight:500"' : ''}>${l}</td>${cos.map(c => `<td class="num">${money(data[c.id][k])}</td>`).join('')}<td class="num" style="font-weight:500">${money(sum(cos, c => data[c.id][k]))}</td></tr>`).join('')}</tbody></table>`, { ic: 'layers' })}`;
}

ACT['bankacct.new'] = () => openForm({ title: 'Add bank account', fields: [{ n: 'name', l: 'Account name', req: true }, { n: 'bank', l: 'Bank', req: true, half: true }, { n: 'acctNo', l: 'Account number', req: true, half: true, vf: v => /^\d{10}$/.test(v) ? '' : 'Enter the 10-digit NUBAN number.' }, { n: 'gl', l: 'Ledger account', t: 'select', blank: false, o: DB.q('accounts').filter(a => a.type === 'asset' && ['1010', '1020'].includes(a.code)).map(a => [a.code, a.code + ' · ' + a.name]) }], vals: { gl: '1010' }, onSubmit: v => { DB.add('bankAccts', v); render(); } });
